files.tests/test_text.py:
from text import truncate


def test_short_value_is_kept():
    assert truncate("hi", 10) == "hi"


def test_long_value_gets_dots():
    assert truncate("a long title for a card", 10).endswith("...")


def test_long_value_is_exactly_width():
    result = truncate("a long title for a card", 10)
    assert result == "a long ..."
    assert len(result) == 10


def test_card_title_width_20():
    assert len(truncate("x" * 50, 20)) == 20


def test_value_of_exact_width_is_kept():
    assert truncate("abcde", 5) == "abcde"


def test_width_below_four_raises():
    import pytest
    for w in (3, 0, -1):
        with pytest.raises(ValueError):
            truncate("abcdef", w)
    with pytest.raises(ValueError):
        truncate("a", 3)


def test_minimum_width_four():
    assert truncate("abcdef", 4) == "a..."

